int op_pick(void) {
  PN = 0;
  for (;;) {
    int best = -1;
    for (int i = 0; i < GN; i++) {
      if (G[i].done) {
        continue;
      }
      if (G[i].indeg == 0) {
        if (best < 0 || i < best) {
          best = i;
        }
      }
    }
    if (best < 0) {
      for (int i = 0; i < GN; i++) {
        if (G[i].done) {
          continue;
        }
        if (best < 0 || i < best) {
          best = i;
        }
      }
    }
    if (best < 0) {
      break;
    }
    PLAN[PN++] = best;
    G[best].done = 1;
    for (int k = 0; k < nsucc[best]; k++) {
      int j = succ[best][k];
      if (G[j].indeg > 0) {
