int n_bind(const char *a) {
  FILE *f;
  FILE *ok;
  char dir[128];
  const char *slash;

  slash = strrchr(a, '/');
  if (slash) {
    size_t n = (size_t)(slash - a);
    if (n >= sizeof dir) {
      n = sizeof dir - 1;
    }
    memcpy(dir, a, n);
    dir[n] = 0;
  } else {
    snprintf(dir, sizeof dir, ".");
  }

  f = fopen(a, "w");
  if (!f) {
    return 2;
  }
  for (int i = 0; i < PN; i++) {
    int k = PLAN[i];
    fprintf(f, "%s\n", G[k].hex);
  }
  fclose(f);

  {
    char okp[160];
    snprintf(okp, sizeof okp, "%s/mill.ok", dir);
    ok = fopen(okp, "w");
    if (ok) {
      fputs("ok\n", ok);
      fclose(ok);
    }
  }
  (void)g_closer;
  return 0;
}
