int scan_dump(const char *path) {
  FILE *f;
  char line[160];
  int open = 0;

  reset_g();
  f = fopen(path, "r");
  if (!f) return 2;

  while (fgets(line, sizeof line, f)) {
    char *nl = strchr(line, '\n');
    if (!nl && !feof(f)) return bad(f); /* overlong record */
    if (nl) *nl = 0;
    if (line[0] == 0) continue;

    if (strncmp(line, "THREAD ", 7) == 0) {
      char *end;
      unsigned long tid;
      if (open || GN >= MAXL) return bad(f);
      errno = 0;
      tid = strtoul(line + 7, &end, 10);
      if (errno || end == line + 7 || *end || tid > UINT32_MAX) return bad(f);
      G[GN].tid = (uint32_t)tid;
      open = 1;
      GN++;
    } else if (!open) {
      return bad(f);
