#include "pick.h"
#include "store.h"

static int before(int a, int b) {
  if (b < 0) return 1;
  if (G[a].tag != G[b].tag) return G[a].tag < G[b].tag;
  if (G[a].tid != G[b].tid) return G[a].tid < G[b].tid;
  return a < b;
}

int op_pick(void) {
  PN = 0;
  while (PN < GN) {
    int best = -1;
    for (int i = 0; i < GN; i++)
      if (!G[i].done && G[i].indeg == 0 && before(i, best)) best = i;
    /* A deadlock has no zero-indegree node. Break it reproducibly. */
    if (best < 0)
      for (int i = 0; i < GN; i++)
        if (!G[i].done && before(i, best)) best = i;
    if (best < 0) return 2;
    PLAN[PN++] = best;
    G[best].done = 1;
    for (int k = 0; k < nsucc[best]; k++) {
      int j = succ[best][k];
      if (G[j].indeg > 0) G[j].indeg--;
    }
  }
  return 0;
}
